pub fn EXISetExiCallback<'a>(ctx: &'a Ctx, chan: i32, exiCallback: FnPtr<'a>) -> FnPtr<'a> {
    let __frame = ctx.stack_frame(0x28);
    let mut chan = chan;
    let mut exiCallback = exiCallback;
    let mut exi: EXIControl<'a> = null(ctx);
    let mut prev: FnPtr<'a> = null(ctx);
    let mut enabled: i32 = 0;
    exi = statics::dolphin__os__OSExi::Ecb(ctx).get(chan);
    enabled = fns::OSDisableInterrupts(ctx);
    prev = (exi).exiCallback();
    (exi).set_exiCallback(exiCallback);
    if chan != 2_i32 {
        statics::dolphin__os__OSExi::SetExiInterruptMask(ctx, chan, exi);
    } else {
        statics::dolphin__os__OSExi::SetExiInterruptMask(
            ctx,
            0_i32,
            statics::dolphin__os__OSExi::Ecb(ctx).get(0_i32),
        );
    }
    let _ = fns::OSRestoreInterrupts(ctx, enabled);
    return prev;
}

